Clase Semaforo
    Privado Definir estado Como Entero;

    Metodo Constructor()
        Este.estado <- 0;
    FinMetodo

    Publico Metodo Siguiente()
        Si Este.estado = 2 Entonces
            Este.estado <- 0;
        SiNo
            Este.estado <- Este.estado + 1;
        FinSi
    FinMetodo

    Publico Metodo Estado() Como Entero
        Retornar Este.estado;
    FinMetodo
FinClase

Proceso EjecutarSemaforo
    Definir veces Como Entero;
    Definir i Como Entero;
    Definir semaforo Como Semaforo;
    Leer veces;
    semaforo <- Nuevo Semaforo();
    Para i <- 1 Hasta veces Con Paso 1 Hacer
        semaforo.Siguiente();
    FinPara
    Escribir semaforo.Estado();
FinProceso
